// 代理类自己、当前执行方法、执行参数、可以避免反射调用的代理对象  
IO._println_("before");  
Object result = methodProxy.invoke(target, args1); // 没用反射，需要目标(Spring)  
result = methodProxy.invokeSuper(obj, args1); // 也没用反射，用代理自己  
IO._println_("after");  
return result;  
});  
proxy.foo();  
}  
