    Node s = node.next;  
    if (s == null || s.waitStatus \> 0) {   //如果下一个结点为空或是等待状态是已取消，那肯定是不能通知unpark的，这时就要遍历所有节点再另外找一个符合unpark要求的节点了  
        s = null;  
