METADATA:{"created":"2026/03/18 18:27:57","modified":"2026/03/18 18:27:57","chunkId":"OneNote/java/源码/参数解析器.md#0","heading":""}

NOTE BLOCK CONTENT:

下面的注解都是参数解析器来的  
@RequestParam  
@PathVariable  
@RequestHeader  
@CookieValue  
@Value()  
@ModelAttribute  
@RequestBody  
参数解析的过程  
// 控制器方法转为HandlerMethod  
HandlerMethod handlerMethod = new HandlerMethod((Controller)  
(request1, response) -\> null  
, Controller.class.getMethod(  
"handleRequest", HttpServletRequest.class, HttpServletResponse.class));  
// 准备对象绑定与类型转换  
ServletRequestDataBinderFactory factory = new ServletRequestDataBinderFactory(null, null);  
// 准备ModelAndViewContainer来存储中间Model对象  
ModelAndViewContainer container = new ModelAndViewContainer();  
// 解析每个参数值  
for (MethodParameter methodParameter : handlerMethod.getMethodParameters()) {  
// 多个解析器的组合  
HandlerMethodArgumentResolverComposite composite = new HandlerMethodArgumentResolverComposite();  
composite.addResolvers(  
// 以@RequestParam为例,参1是bean对象，参2表示该注解是否可省略(即解析不带该注解的参数)  
// 我们给它BeanFactory这样就能基于它来解析${}  
new RequestParamMethodArgumentResolver(beanFactory, false)  
// @PathVariable  
, new PathVariableMethodArgumentResolver()  
// @RequestHeader  
, new RequestHeaderMethodArgumentResolver(beanFactory)  
// @CookieValue  
, new ServletCookieValueMethodArgumentResolver(beanFactory)  
// @Value  
, new ExpressionValueMethodArgumentResolver(beanFactory)  
// 解析参数里的HttpServletRequest  
, new ServletRequestMethodArgumentResolver()  
// 把参数绑定到Model对象里，参数代表是否必须要@ModelAttribute注解  
, new ServletModelAttributeMethodProcessor(false)  
// @RequestBody  
, new RequestResponseBodyMethodProcessor(List._of_(new MappingJackson2HttpMessageConverter()))  
// 是前面的那个的保底，解析不带注解的，Spring就是这样的  
// 要注意与上面的顺序不能调换，要不然是解析param到POJO了  
, new ServletModelAttributeMethodProcessor(true));


if (composite.supportsParameter(methodParameter)) {  
// 如果支持该参数  
// 解析参数：方法参数对象、缓存的Model容器，Spring封装的请求对象、绑定的类型转换工厂  
Object object = composite.resolveArgument(methodParameter, container  
, new ServletWebRequest(request), factory);  
}  
}  
获取参数名  
一般情况下javac编译的方法参数名会丢失，可以使用以下方法  
添加-parameters参数(可通过反射获取参数名)  
使用-g选项(生成老师信息、本地变量表（接口不生成）不可通过反射获取，但是ASM可以)  
Spring中是把这两种都用了  
public class DefaultParameterNameDiscoverer extends PrioritizedParameterNameDiscoverer {  
public DefaultParameterNameDiscoverer() {  
if (KotlinDetector._isKotlinReflectPresent_()) {  
addDiscoverer(new KotlinReflectionParameterNameDiscoverer());  
}  
// Recommended approach on Java 8+: compilation with -parameters.  
addDiscoverer(new StandardReflectionParameterNameDiscoverer());  
}

}

